612	                'Bỏ qua seed: không tìm thấy category slug="%s"%s.',
613	                $definition['slug'],
614	                $definition['parent_slug'] !== null ? sprintf(' dưới parent slug="%s"', $definition['parent_slug']) : ''
615	            ));
616	
617	            return;
618	        }
619	
620	        $foundation = CategoryContentFoundation::query()
621	            ->whereHas('categories', fn ($q) => $q->where('post_categories.id', $category->id))
622	            ->first() ?? new CategoryContentFoundation();
623	
624	        $foundation->fill([
625	            'core_focus'     => $definition['core_focus'],
626	            'unique_angle'   => $definition['unique_angle'],
627	            'content_goals'  => $definition['content_goals'],
628	            'pain_points'    => $definition['pain_points'],
629	            'rejected_ideas' => $definition['rejected_ideas'],
630	            'audience'       => $definition['audience'],
631	            'constraints'    => $definition['constraints'],
632	            'style_sample'   => $definition['style_sample'],
633	        ]);
634	
635	        $foundation->save();
636	        $foundation->categories()->syncWithoutDetaching([$category->id]);
637	
638	        $this->command?->info(sprintf(
